node -e '
const fs = require("node:fs");
const assert = require("node:assert/strict");
const dir = process.argv[1];
const d = JSON.parse(fs.readFileSync(dir + "/analysis-data.json", "utf8"));
const report = fs.readFileSync(dir + "/output.md", "utf8");
const lists = [
["source_register","source_id"],["objectives","objective_id"],["requirements","requirement_id"],
["end_to_end_processes","end_to_end_process_id"],["process_reference_mappings","process_reference_mapping_id"],
["processes","process_id"],["steps","step_id"],["process_observations","observation_id"],
["risks","risk_id"],["control_objectives","control_objective_id"],["controls","control_id"],
["baseline_links","baseline_link_id"],["control_observations","control_observation_id"],
["comparisons","comparison_id"],["gaps","gap_id"],["dependencies","dependency_id"],
["sod_assessments","sod_conflict_id"],["design_opportunities","design_opportunity_id"],
["no_change_scenarios","no_change_scenario_id"],["recommendations","recommendation_id"],
["actions","action_id"],["metrics","metric_id"],["test_attributes","test_attribute_id"],
["relationships","relationship_id"],["rcm_relationships","rcm_id"]
];
const allIds = new Set();
for (const [list,key] of lists) {
 const ids = d[list].map(x=>x[key]);
 assert.equal(new Set(ids).size, ids.length, "duplicate in " + list);
 ids.forEach(id=>{assert.ok(id); allIds.add(id);});
}
const sources = new Set(d.source_register.map(x=>x.source_id));
const controls = new Map(d.controls.map(x=>[x.control_id,x]));
const risks = new Set(d.risks.map(x=>x.risk_id));
const observations = new Map(d.control_observations.map(x=>[x.control_observation_id,x]));
const evidence = new Set(d.source_register.filter(x=>x.evidence_id).map(x=>x.evidence_id));
function scan(x) {
 if(!x || typeof x !== "object") return;
 if(Array.isArray(x)){x.forEach(scan);return;}
 for (const [k,v] of Object.entries(x)) {
  if(k==="source_ids") v.forEach(id=>assert.ok(sources.has(id),"unknown source "+id));
  if(k==="evidence_ids") v.forEach(id=>assert.ok(evidence.has(id),"unknown evidence "+id));
  scan(v);
 }
}
scan(d);
for(const o of observations.values()) {
 assert.ok(controls.has(o.control_id));
 o.risk_ids.forEach(id=>assert.ok(risks.has(id)));
 if(o.analysis_layer==="As-Performed") assert.ok(o.evidence_ids.length>0);
}
for(const row of d.rcm_relationships) {
 const o=observations.get(row.control_observation_id);
 assert.ok(o);
 assert.equal(row.control_id,o.control_id);
 assert.equal(row.analysis_layer,o.analysis_layer);
 assert.equal(row.assessed_scope,o.assessed_scope);
 assert.equal(row.assessed_period,o.assessed_period);
 assert.ok(o.risk_ids.includes(row.risk_id));
}
for(const c of d.comparisons) {
 for(const [key,layer] of Object.entries({
 documented_observation_ids:"As-Documented",
 designed_observation_ids:"As-Designed",
 performed_observation_ids:"As-Performed",
 target_observation_ids:"Target-State"
 })) for(const id of c[key]){
  const o=observations.get(id); assert.ok(o); assert.equal(o.analysis_layer,layer);
  assert.ok(c.logical_control_ids.includes(o.control_id));
 }
}
for(const r of d.relationships) {
 assert.ok(allIds.has(r.from_id),"unknown from "+r.from_id);
 assert.ok(allIds.has(r.to_id),"unknown to "+r.to_id);
}
for(const a of d.actions) {
 assert.equal(a.owner,null); assert.equal(a.target_date,null);
 assert.equal(a.budget,null); assert.equal(a.status,"Draft");
 for(const id of [...a.gap_ids,...(a.design_opportunity_ids||[]),...a.comparison_ids,...a.no_change_scenario_ids,...a.dependencies]) assert.ok(allIds.has(id));
}
for(const n of d.no_change_scenarios) {
 assert.equal(n.horizon,null); assert.equal(n.probability,null); assert.equal(n.loss,null);
}
assert.equal(d.controls.filter(c=>c.control_id==="CTL-SHARED-19").length,1);
assert.equal(d.controls.length,3);
assert.equal(d.control_observations.length,7);
assert.equal(d.rcm_relationships.length,13);
assert.equal(observations.get("OBS-19-P01").raw_status,"VERIFIED");
assert.equal(observations.get("OBS-19-P02").raw_status,"PENDING_REVIEW");
assert.deepEqual(observations.get("OBS-19-P01").process_ids,[]);
for(const id of ["CTL-SHARED-19","OBS-19-P01","OBS-19-P02","ACT-19-01","NCS-19-01"]) assert.ok(report.includes(id),"missing report reference "+id);
console.log(JSON.stringify({json_parse:"ok",id_uniqueness:"ok",source_evidence_links:"ok",relationship_endpoints:"ok",rcm_observation_identity_layer_scope_period:"ok",comparison_layers:"ok",raw_status_preservation:"ok",null_owner_dates_budget_horizon:"ok",counts:{controls:d.controls.length,control_observations:d.control_observations.length,risks:d.risks.length,gaps:d.gaps.length,actions:d.actions.length,rcm_rows:d.rcm_relationships.length,relationships:d.relationships.length},limitations:"Structural checks only; no business/OE assurance or source reconciliation."},null,2));
' /private/tmp/thien-rpc-phase3.xGeed0/P1-U19-V01-R2
